1	import { redirect } from "next/navigation";
2	import Link from "next/link";
3	import { getCurrentUser } from "@/lib/auth";
4	import { getSpendCapStatus, spentInWindow } from "@/lib/credits";
5	import {
6	  MIN_ACCOUNT_AGE_HOURS,
7	  rewardStatuses,
8	  UNVERIFIED_HOLD_HOURS,
9	} from "@/app/api/rewards/_lib";
10	import RewardsCard from "@/components/rewards/RewardsCard";
