15	export default async function SettingsPage({
16	  searchParams,
17	}: {
18	  searchParams: Promise<Record<string, string | string[] | undefined>>;
19	}) {
20	  const user = await getCurrentUser();
21	  if (!user) redirect("/login");
22	
23	  const cap = await getSpendCapStatus(user.id);
24	  // getSpendCapStatus skips the spend query when uncapped (nothing to compare
25	  // against), but this page shows recent spend either way.
26	  const spent = cap.cap === null ? await spentInWindow(user.id) : cap.spent;
27	
28	  // Returns [] when no reward is configured, so the card renders nothing at
29	  // all rather than this page needing to know anything about env vars.
30	  const rewards = await rewardStatuses(user);
31	
32	  // Set by the Discord OAuth callback on its way back here.
33	  const notice = (await searchParams).reward;
34	
35	  return (
36	    <div className="mx-auto max-w-2xl px-6 py-10">
37	      <div className="mb-8">
38	        <Link
39	          href="/dashboard"
40	          className="text-sm text-black/60 underline underline-offset-2 hover:no-underline dark:text-white/60"
41	        >
42	          ← Back
43	        </Link>
44	        <h1 className="mt-3 text-lg font-semibold tracking-tight">Settings</h1>
45	        <p className="text-sm text-black/60 dark:text-white/60">{user.email}</p>
46	      </div>
47	
48	      <SpendCapForm initialCap={cap.cap} spent={spent} />
49	
50	      <RewardsCard
51	        rewards={rewards}
52	        holdHours={UNVERIFIED_HOLD_HOURS}
53	        unlockHours={MIN_ACCOUNT_AGE_HOURS}
54	        notice={typeof notice === "string" ? notice : undefined}
55	      />
56	    </div>
57	  );
58	}
