1	import { requireUser } from "@/lib/auth";
2	import { isMailConfigured, sendMail } from "@/lib/mail";
3	import {
4	  CONFIRMATION_PHRASE,
5	  DELETION_GRACE_DAYS,
6	  PRIVACY_EMAIL,
7	  cancelDeletion,
8	  deletionPreview,
9	  deletionStatus,
10	  requestDeletion,
11	} from "../_deletion";
12	
13	export const dynamic = "force-dynamic";
14	
15	// Step one of two. This route can only ever CREATE or WITHDRAW a request —
16	// nothing it does destroys anything. Erasure lives at ./confirm, behind the
17	// grace period, so that no single request to a single URL can end an account.
18	
19	/** Current state plus what erasure would destroy. */
20	export async function GET() {
21	  const user = await requireUser().catch(() => null);
22	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
23	
24	  const [status, preview] = await Promise.all([
25	    deletionStatus(user.id),
26	    deletionPreview(user.id),
27	  ]);
28	
29	  return Response.json({
30	    status,
31	    preview,
32	    graceDays: DELETION_GRACE_DAYS,
33	    confirmationPhrase: CONFIRMATION_PHRASE,
34	    contactEmail: PRIVACY_EMAIL,
35	  });
36	}
37	
38	/** Open a request. */
39	export async function POST(req: Request) {
40	  const user = await requireUser().catch(() => null);
41	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
42	
43	  const body = (await req.json().catch(() => null)) as { confirm?: unknown } | null;
44	  if (body?.confirm !== CONFIRMATION_PHRASE) {
45	    return Response.json(
46	      { error: `Type ${CONFIRMATION_PHRASE} exactly to continue.` },
47	      { status: 400 },
48	    );
49	  }
50	
51	  const result = await requestDeletion(user.id, user.email);
52	  if (!result.ok) {
53	    return Response.json(
54	      {
55	        error:
56	          result.reason === "erased"
57	            ? "This account has already been erased."
58	            : "There is already an open deletion request for this account.",
59	      },
60	      { status: 409 },
61	    );
62	  }
63	
64	  // The one notification that matters for security. A deletion request made
65	  // from a stolen session is invisible to the owner until their work is gone;
66	  // an email lands in an inbox the attacker may not hold, while there is still
67	  // a week in which to cancel. Never allowed to fail the request — an
68	  // unsendable email must not stop someone exercising a right.
69	  if (isMailConfigured()) {
70	    const scheduled =
71	      result.status.state === "pending" || result.status.state === "due"
72	        ? result.status.scheduledFor.toISOString()
73	        : "shortly";
74	    try {
75	      await sendMail({
76	        to: user.email,
77	        subject: "Your Kodely account is scheduled for deletion",
78	        text:
79	          `Someone signed in to your Kodely account and asked us to delete it.\n\n` +
80	          `Nothing has been deleted yet. The request cannot be carried out before\n` +
81	          `${scheduled} (${DELETION_GRACE_DAYS} days from now), and until then your\n` +
82	          `account works exactly as before.\n\n` +
83	          `If this was you, no action is needed — sign in and confirm after that date\n` +
84	          `to complete it: https://kodely.me/legal/rights\n\n` +
85	          `If this was NOT you, someone else has access to your account. Cancel the\n` +
86	          `request at the link above, change your password, and email us at\n` +
87	          `${PRIVACY_EMAIL}.\n`,
88	      });
89	    } catch (err) {
90	      console.error("[account-deletion] failed to send request notice:", err);
91	    }
92	  }
93	
94	  return Response.json({ status: result.status });
95	}
96	
97	/** Withdraw a request. */
98	export async function DELETE() {
99	  const user = await requireUser().catch(() => null);
100	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
101	
102	  const cancelled = await cancelDeletion(user.id);
103	  if (!cancelled) {
104	    return Response.json({ error: "There is no open deletion request." }, { status: 409 });
105	  }
106	
107	  return Response.json({ status: await deletionStatus(user.id) });
108	}
