1	import { destroySession, requireUser } from "@/lib/auth";
2	import { isMailConfigured, sendMail } from "@/lib/mail";
3	import {
4	  CONFIRMATION_PHRASE,
5	  DELETION_GRACE_DAYS,
6	  PRIVACY_EMAIL,
7	  deletionStatus,
8	  eraseAccount,
9	} from "../../_deletion";
10	
11	export const dynamic = "force-dynamic";
12	
13	// Step two of two, and the only irreversible route in this directory.
14	//
15	// It refuses unless ALL of these hold:
16	//   * a request exists and its grace period has elapsed (state "due");
17	//   * the confirmation phrase is typed again, exactly;
18	//   * the caller is signed in as the account being erased.
19	//
20	// There is no admin path here and no way to name another account: the id comes
21	// from the session and nowhere else.
22	
23	export async function POST(req: Request) {
24	  const user = await requireUser().catch(() => null);
25	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
26	
27	  const body = (await req.json().catch(() => null)) as { confirm?: unknown } | null;
28	  if (body?.confirm !== CONFIRMATION_PHRASE) {
29	    return Response.json(
30	      { error: `Type ${CONFIRMATION_PHRASE} exactly to continue.` },
31	      { status: 400 },
32	    );
33	  }
34	
35	  const status = await deletionStatus(user.id);
36	
37	  if (status.state === "erased") {
38	    return Response.json({ error: "This account has already been erased." }, { status: 409 });
39	  }
40	  if (status.state === "none") {
41	    return Response.json(
42	      {
43	        error: `Request deletion first. Nothing is erased until ${DELETION_GRACE_DAYS} days after a request.`,
44	      },
45	      { status: 409 },
46	    );
47	  }
48	  if (status.state === "pending") {
49	    return Response.json(
50	      {
51	        error: `This request can't be carried out until ${status.scheduledFor.toISOString()}.`,
52	        status,
53	      },
54	      { status: 409 },
55	    );
56	  }
57	
58	  // Captured before erasure destroys it.
59	  const email = user.email;
60	
61	  const receipt = await eraseAccount(user.id);
62	
63	  // Every session row is gone, so the cookie is already inert — this clears it
64	  // from the browser so the next page load reads as signed out immediately
65	  // rather than as an expired session.
66	  await destroySession();
67	
68	  // Sent after the fact, deliberately: this says what happened, not what is
69	  // about to. If it fails, the erasure still stands.
70	  if (isMailConfigured()) {
71	    try {
72	      await sendMail({
73	        to: email,
74	        subject: "Your Kodely account has been deleted",
75	        text:
76	          `Your Kodely account has been deleted, as you asked.\n\n` +
77	          `Deleted: ${receipt.projectsDeleted} project(s), ${receipt.filesDeleted} file(s), ` +
78	          `${receipt.messagesDeleted} message(s), ${receipt.buildsDeleted} build(s), and your\n` +
79	          `sign-in details. ${receipt.liveSitesWithdrawn} published site(s) were taken offline.\n\n` +
80	          `Kept: ${receipt.creditLedgerRowsRetained} credit ledger entries, as a financial record.\n` +
81	          `They no longer carry your email address, name or any other identifier.\n` +
82	          `${receipt.analyticsEventsDetached} analytics event(s) were detached from your account\n` +
83	          `rather than deleted.\n\n` +
84	          `Why, in full: https://kodely.me/legal/rights\n` +
85	          `Questions: ${PRIVACY_EMAIL}\n`,
86	      });
87	    } catch (err) {
88	      console.error("[account-deletion] failed to send completion notice:", err);
89	    }
90	  }
91	
92	  return Response.json({ receipt });
93	}
