3	import { useState } from "react";
4	
5	type Props = { initialCap: number | null; spent: number };
6	
7	export default function SpendCapForm({ initialCap, spent }: Props) {
8	  const [enabled, setEnabled] = useState(initialCap !== null);
9	  const [value, setValue] = useState(initialCap === null ? "" : String(initialCap));
10	  const [saving, setSaving] = useState(false);
11	  const [message, setMessage] = useState<{ kind: "ok" | "error"; text: string } | null>(null);
12	
13	  async function save() {
14	    setSaving(true);
15	    setMessage(null);
16	
17	    const cap = enabled ? Number(value) : null;
18	    if (enabled && (!Number.isInteger(cap) || (cap as number) < 1)) {
19	      setMessage({ kind: "error", text: "Enter a whole number of credits." });
20	      setSaving(false);
21	      return;
22	    }
23	
24	    try {
25	      const res = await fetch("/api/account/spend-cap", {
26	        method: "PUT",
27	        headers: { "Content-Type": "application/json" },
28	        body: JSON.stringify({ cap }),
29	      });
30	      const data = await res.json();
31	      if (!res.ok) {
32	        setMessage({ kind: "error", text: data.error ?? "Couldn't save that." });
33	      } else {
34	        setMessage({
35	          kind: "ok",
36	          text: data.cap === null ? "Cap removed." : `Cap set to ${data.cap} credits.`,
37	        });
38	      }
39	    } catch {
40	      setMessage({ kind: "error", text: "Couldn't reach the server. Try again." });
41	    } finally {
42	      setSaving(false);
43	    }
44	  }
45	
46	  return (
47	    <div className="rounded-xl border border-black/10 p-5 dark:border-white/10">
48	      <h2 className="text-sm font-medium">Spending cap</h2>
49	      <p className="mt-1 text-sm text-black/60 dark:text-white/60">
50	        Stop builds once you&apos;ve spent this many credits in any 30-day period. Your cap,
51	        your call — we&apos;ll never raise it for you. You&apos;ve used{" "}
52	        <span className="font-medium tabular-nums">{spent}</span> in the last 30 days.
53	      </p>
54	
55	      <label className="mt-4 flex items-center gap-2 text-sm">
56	        <input
57	          type="checkbox"
58	          checked={enabled}
59	          onChange={(e) => {
60	            setEnabled(e.target.checked);
61	            setMessage(null);
62	          }}
63	          className="h-4 w-4 rounded border-black/20 dark:border-white/20"
64	        />
65	        Limit my spending
66	      </label>
67	
68	      {enabled && (
69	        <div className="mt-3 flex items-center gap-2">
70	          <input
71	            type="number"
72	            min={1}
73	            step={1}
74	            value={value}
75	            onChange={(e) => {
76	              setValue(e.target.value);
77	              setMessage(null);
78	            }}
79	            placeholder="1000"
80	            className="w-32 rounded-lg border border-black/15 bg-transparent px-3 py-1.5 text-sm tabular-nums outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40"
81	          />
82	          <span className="text-sm text-black/60 dark:text-white/60">credits per 30 days</span>
83	        </div>
84	      )}
85	
86	      <div className="mt-4 flex items-center gap-3">
87	        <button
88	          onClick={save}
89	          disabled={saving}
90	          className="rounded-lg bg-black px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50 dark:bg-white dark:text-black"
91	        >
92	          {saving ? "Saving…" : "Save"}
93	        </button>
94	        {message && (
95	          <span
96	            className={
97	              message.kind === "ok"
98	                ? "text-sm text-emerald-600 dark:text-emerald-400"
99	                : "text-sm text-red-600 dark:text-red-400"
100	            }
101	          >
102	            {message.text}
103	          </span>
104	        )}
105	      </div>
106	    </div>
107	  );
108	}
