5	export type SegmentOption<T extends string> = {
6	  value: T;
7	  label: string;
8	  /** When set, the label is hidden and this is the accessible name — used by
9	      the grid/list and device toggles, which are icon-only by convention. */
10	  iconOnly?: boolean;
11	  icon?: ReactNode;
12	};
13	
14	/* A radio group wearing a segmented control's clothes. Real radios, not
15	   buttons: arrow-key navigation between options and single-tab-stop
16	   behaviour are what the customer's keyboard already expects from a
17	   this-or-that choice, and neither comes free with <button>. */
18	export function Segmented<T extends string>({
19	  name,
20	  value,
21	  onChange,
22	  options,
23	  size = "md",
24	  className = "",
25	  ariaLabel,
26	}: {
27	  name: string;
28	  value: T;
29	  onChange: (v: T) => void;
30	  options: SegmentOption<T>[];
31	  size?: "sm" | "md";
32	  className?: string;
33	  ariaLabel: string;
34	}) {
35	  const h = size === "sm" ? "h-7" : "h-8";
36	  return (
37	    <div
38	      role="radiogroup"
39	      aria-label={ariaLabel}
40	      className={`inline-flex items-center gap-0.5 rounded-md border border-hair bg-surface-2 p-0.5 ${className}`}
41	    >
42	      {options.map((o) => {
43	        const active = o.value === value;
44	        return (
45	          <label
46	            key={o.value}
47	            title={o.iconOnly ? o.label : undefined}
48	            className={[
49	              "relative inline-flex cursor-pointer items-center justify-center gap-1.5 rounded-[6px] px-2.5 text-[0.8125rem] font-medium",
50	              h,
51	              active
52	                ? "bg-surface text-ink shadow-e1"
53	                : "text-ink-2 hover:text-ink",
54	              "transition-colors duration-[var(--t-1)] has-[:focus-visible]:outline has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-[var(--brand-ring)]",
55	            ].join(" ")}
56	          >
57	            <input
58	              type="radio"
59	              name={name}
60	              value={o.value}
61	              checked={active}
62	              onChange={() => onChange(o.value)}
63	              className="sr-only"
64	            />
65	            {o.icon}
66	            {o.iconOnly ? <span className="sr-only">{o.label}</span> : o.label}
67	          </label>
68	        );
69	      })}
70	    </div>
71	  );
72	}
