182	  onHandle: (value: string) => void;
183	  onConnect: () => void;
184	  onClaim: () => void;
185	}) {
186	  const muted = "text-sm text-black/50 dark:text-white/50";
187	  const button =
188	    "rounded-lg bg-black px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50 dark:bg-white dark:text-black";
189	  const link =
190	    "text-sm text-black/60 underline underline-offset-2 hover:no-underline dark:text-white/60";
