192	  if (reward.state === "claimed") {
193	    return <span className="text-sm text-emerald-600 dark:text-emerald-400">Claimed</span>;
194	  }
195	
196	  if (reward.state === "locked") {
197	    return <span className={muted}>Unlocks {unlockHours}h after signup</span>;
198	  }
199	
200	  if (reward.state === "pending") {
201	    return (
202	      <span className={muted}>
203	        Connected — credits in {formatHours(reward.readyInHours ?? holdHours)}
204	      </span>
205	    );
206	  }
207	
208	  if (reward.state === "claimable") {
209	    return (
210	      <button onClick={onClaim} disabled={busy} className={button}>
211	        {busy ? "Claiming…" : `Claim ${reward.credits}`}
212	      </button>
213	    );
214	  }
