224	        <a href="/api/rewards/discord/start" className={button}>
225	          Verify
226	        </a>
227	      </div>
228	    );
229	  }
230	
231	  return (
232	    <div className="flex flex-wrap items-center gap-2">
233	      <a href={reward.url} target="_blank" rel="noreferrer noopener" className={link}>
234	        Open
235	      </a>
236	      <input
237	        value={handle}
238	        onChange={(e) => onHandle(e.target.value)}
239	        placeholder="your username"
240	        aria-label={`Your ${reward.label} username`}
241	        className="w-40 rounded-lg border border-black/15 bg-transparent px-3 py-1.5 text-sm outline-none focus:border-black/40 dark:border-white/15 dark:focus:border-white/40"
242	      />
243	      <button onClick={onConnect} disabled={busy} className={button}>
244	        {busy ? "Saving…" : "I followed"}
245	      </button>
246	    </div>
247	  );
248	}
