250	function formatHours(hours: number): string {
251	  if (hours <= 1) return "under an hour";
252	  if (hours < 24) return `${hours} hours`;
253	  const days = Math.ceil(hours / 24);
254	  return days === 1 ? "a day" : `${days} days`;
255	}
