// ── The one editable field on the account: User.name ──────────────────────
//
// The column has existed since the first migration and is written in exactly
// two places — the signup route and the Google callback — and read all over
// the portal ("Welcome back, <name>", the sidebar, the avatar's initials, the
// welcome email). Until now there was no way to change it after the fact,
// which meant a typo at signup was permanent and a Google display name could
// never be corrected.
//
// Normalisation lives here rather than inside the route so the form and the
// route agree on the same limit and the same rules, instead of the client
// guessing at a cap the server will enforce differently.

/**
 * Deliberately generous but finite. The name is rendered inline in a sidebar
 * 248px wide and in an email subject line; 80 characters is longer than any
 * real name and short enough that no layout has to defend against it. There is
 * no length check at signup today, so this is also the first cap the column
 * has ever had — it is enforced on write, not retroactively.
 */
export const MAX_NAME_LENGTH = 80;

/**
 * Anything longer than this is refused before normalisation runs, so a
 * megabyte of text is never walked character by character.
 */
const MAX_RAW_LENGTH = 4_000;

export type NameResult = { ok: true; name: string | null } | { ok: false; error: string };

/**
 * Characters removed rather than rejected, because none of them is something a
 * person meant to type:
 *
 *   * C0/C7 control characters, including the newlines and tabs a paste from a
 *     document carries in;
 *   * zero-width space/joiner/non-joiner and the byte-order mark, which make a
 *     name that looks identical to another one;
 *   * the bidirectional overrides (LRM/RLM, LRE…RLO, the isolates). This name
 *     is rendered inline next to other text — "Welcome back, <name>" — and an
 *     unterminated RLO reverses the rest of the line, so a display name could
 *     scramble the sentence around it. React escapes markup; it does not
 *     escape text direction.
 */
function isStrippable(code: number): boolean {
  if (code < 0x20 || code === 0x7f) return true;
  if (code >= 0x80 && code <= 0x9f) return true;
  if (code >= 0x200b && code <= 0x200f) return true;
  if (code >= 0x202a && code <= 0x202e) return true;
  if (code >= 0x2066 && code <= 0x2069) return true;
  return code === 0xfeff;
}

/**
 * `null` and the empty string both mean "clear it" — the column is nullable
 * and an empty-string name would render as a blank space where a name is
 * expected, which is a third state nothing in the product knows how to show.
 */
export function normalizeName(raw: unknown): NameResult {
  if (raw === null) return { ok: true, name: null };
  if (typeof raw !== "string") {
    return { ok: false, error: "A name has to be text. Send null to clear it." };
  }
  if (raw.length > MAX_RAW_LENGTH) {
    return { ok: false, error: `Keep your name to ${MAX_NAME_LENGTH} characters or fewer.` };
  }

  let cleaned = "";
  for (const character of raw) {
    const code = character.codePointAt(0) ?? 0;
    cleaned += isStrippable(code) ? " " : character;
  }
  cleaned = cleaned.replace(/\s+/g, " ").trim();

  if (cleaned.length === 0) return { ok: true, name: null };
  // Counted in code points, not UTF-16 units, so an emoji or an astral-plane
  // character costs one the way it looks like one.
  if (Array.from(cleaned).length > MAX_NAME_LENGTH) {
    return { ok: false, error: `Keep your name to ${MAX_NAME_LENGTH} characters or fewer.` };
  }
  return { ok: true, name: cleaned };
}

import { getCurrentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { normalizeName } from "../_profile";

export const dynamic = "force-dynamic";

// The only field on this route is `name`, and that is not an oversight:
//
//   * EMAIL is not editable anywhere in the product. Changing it would have to
//     re-check uniqueness, invalidate the Google link that resolves an account
//     by googleId, and prove the new address belongs to the person asking —
//     none of which exists. A field that silently refused to save would be
//     worse than the read-only line the settings page shows instead.
//   * PASSWORD has no write path after signup. Nothing in app/api writes
//     passwordHash except the signup route, so there is nothing to call.
//   * ROLE is set by an operator, never by the account holder.
//
// Scoped by the session's own user id, which is the only id this route ever
// reads: there is no way to name another account.

export async function GET() {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });

  return Response.json({ name: user.name, email: user.email });
}

export async function PUT(req: Request) {
  const user = await getCurrentUser();
  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });

  const body: unknown = await req.json().catch(() => null);
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return Response.json({ error: "Send a JSON object with a name." }, { status: 400 });
  }

  // hasOwnProperty rather than `"name" in body`: `in` walks the prototype
  // chain, so a body of {} would report a name of Object.prototype.name and
  // clear a real one. Own properties only.
  if (!Object.prototype.hasOwnProperty.call(body, "name")) {
    return Response.json({ error: "Send a JSON object with a name." }, { status: 400 });
  }

  const result = normalizeName((body as { name: unknown }).name);
  if (!result.ok) return Response.json({ error: result.error }, { status: 400 });

  await db.user.update({ where: { id: user.id }, data: { name: result.name } });

  // The normalised value, not the submitted one — the caller should render
  // what was actually stored rather than the text it sent.
  return Response.json({ name: result.name });
}

import { db } from "@/lib/db";

// ── Active sign-in sessions, as the account holder can honestly be shown ───
//
// WHAT THE Session MODEL ACTUALLY RECORDS (prisma/schema.prisma):
//
//     id        String   @id @default(cuid())
//     userId    String
//     tokenHash String   @unique   // SHA-256 of the cookie value
//     expiresAt DateTime
//     createdAt DateTime @default(now())
//
// That is the entire row, and lib/auth.ts writes nothing else into it. There
// is NO user agent, NO IP address, NO last-seen timestamp, NO device or
// location, and no other table joins to it. So a session can be described with
// exactly three true facts: when the sign-in happened, when it stops working,
// and whether it is the one making the request.
//
// WHY NO COLUMNS WERE ADDED FOR THE REST. It would have been a two-line schema
// change, and it was rejected on purpose:
//
//   * A user agent and an IP address are new personal data. Both /legal/rights
//     and app/api/account/export/route.ts enumerate, in writing, everything the
//     product database holds — the export even lists "IP addresses … live
//     outside the product database" under what is deliberately NOT included.
//     Adding an IP column silently makes both of those documents wrong.
//   * `lastSeenAt` cannot be maintained without a database WRITE on every
//     authenticated request, because getCurrentUser is what every page and
//     route calls. That is a real cost for a cosmetic column.
//
// Neither is impossible; both are product decisions with consequences outside
// this directory, and inventing "Chrome on Windows · London" from a row that
// records none of it would be the exact fabrication the audit warns against.

/** What the UI is allowed to say about one session. Nothing more is known. */
export type SessionRow = {
  id: string;
  /** ISO. Creation time IS the sign-in time — a session is created by signing in. */
  createdAt: string;
  /** ISO. Fixed at creation (30 days); nothing in the product extends it. */
  expiresAt: string;
  /** True for exactly one row in a list: the session making the request. */
  current: boolean;
};

/**
 * Cap on rows returned. Every sign-in mints a session and nothing prunes them
 * before they expire, so an account that signs in daily on several devices can
 * accumulate a lot of live rows. The list is newest-first and the total is
 * reported alongside, so a truncated list says so rather than looking complete.
 */
export const SESSION_LIST_LIMIT = 50;

export type SessionList = {
  sessions: SessionRow[];
  /** Live sessions in total, which may exceed `sessions.length`. */
  total: number;
  limit: number;
};

/**
 * Live sessions only.
 *
 * Expired rows are excluded rather than shown as "expired": they are already
 * inert — getCurrentUser rejects them — and listing dead credentials under a
 * heading that says "active" invites someone to revoke something that stopped
 * working weeks ago and believe they have just secured their account.
 *
 * Scoped by userId inside the same query as every other filter, the rule the
 * export and deletion routes follow: another account's row has to be
 * indistinguishable from a row that does not exist.
 */
export async function listSessions(
  userId: string,
  currentSessionId: string | null,
): Promise<SessionList> {
  const now = new Date();
  const where = { userId, expiresAt: { gt: now } };

  const [rows, total] = await Promise.all([
    db.session.findMany({
      where,
      // Id breaks a timestamp tie so the order is total rather than merely
      // mostly-defined; cuids sort by generation time, so the newer row wins.
      orderBy: [{ createdAt: "desc" }, { id: "desc" }],
      select: { id: true, createdAt: true, expiresAt: true },
      take: SESSION_LIST_LIMIT,
    }),
    db.session.count({ where }),
  ]);

  return {
    sessions: rows.map((row) => ({
      id: row.id,
      createdAt: row.createdAt.toISOString(),
      expiresAt: row.expiresAt.toISOString(),
      current: row.id === currentSessionId,
    })),
    total,
    limit: SESSION_LIST_LIMIT,
  };
}

import { destroySession, getCurrentSession } from "@/lib/auth";
import { db } from "@/lib/db";
import { listSessions } from "../_sessions";

export const dynamic = "force-dynamic";

// ── Listing and revoking sign-in sessions ─────────────────────────────────
//
// Every handler resolves the CURRENT SESSION rather than just the current
// user, because both of them need the caller's own session id: the list has to
// mark exactly one row "this device", and the revoke has to know which row it
// must not quietly delete out from under the person pressing the button.
//
// Three shapes of revoke, and the difference between them is the whole point:
//
//   { "id": "<session id>" }   one other session. Refused for the caller's own
//                              — that is signing out, and it is a different
//                              button with a different consequence.
//   { "scope": "others" }      every session except this one. The safe "all":
//                              the person stays signed in here.
//   { "scope": "all" }         every session INCLUDING this one, and the cookie
//                              is cleared so the browser reads as signed out
//                              immediately rather than as an expired session.
//                              Only ever reached from a control that says so.
//
// Nothing here can act on another account: the user id comes from the session
// and is repeated inside every WHERE, so a session id belonging to someone else
// is indistinguishable from one that does not exist.

export async function GET() {
  const session = await getCurrentSession();
  if (!session) return Response.json({ error: "Not signed in." }, { status: 401 });

  return Response.json(await listSessions(session.userId, session.id));
}

export async function DELETE(req: Request) {
  const session = await getCurrentSession();
  if (!session) return Response.json({ error: "Not signed in." }, { status: 401 });

  const body: unknown = await req.json().catch(() => null);
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    return Response.json(
      { error: "Send a JSON object with either an id or a scope." },
      { status: 400 },
    );
  }

  // hasOwnProperty, never `in`: `in` walks the prototype chain, so `{}` would
  // appear to carry every key on Object.prototype and this route would try to
  // revoke a session named after a built-in.
  const hasId = Object.prototype.hasOwnProperty.call(body, "id");
  const hasScope = Object.prototype.hasOwnProperty.call(body, "scope");

  // Exactly one of them. Both together is ambiguous about what should happen
  // to the named session, and neither is a request with no verb in it.
  if (hasId === hasScope) {
    return Response.json(
      { error: "Send either one session id or a scope, not both." },
      { status: 400 },
    );
  }

  if (hasScope) {
    const scope = (body as { scope: unknown }).scope;
    if (scope !== "others" && scope !== "all") {
      return Response.json({ error: 'Scope must be "others" or "all".' }, { status: 400 });
    }

    if (scope === "others") {
      const { count } = await db.session.deleteMany({
        where: { userId: session.userId, NOT: { id: session.id } },
      });
      return Response.json({ revoked: count, signedOut: false });
    }

    const { count } = await db.session.deleteMany({ where: { userId: session.userId } });
    // The row behind this cookie is already gone, so the cookie is inert.
    // Clearing it is what makes the next page load read as signed out instead
    // of as a session that mysteriously stopped working — the same reasoning
    // as the deletion/confirm route.
    await destroySession();
    return Response.json({ revoked: count, signedOut: true });
  }

  const id = (body as { id: unknown }).id;
  if (typeof id !== "string" || id.length === 0 || id.length > 64) {
    return Response.json({ error: "That is not a session id." }, { status: 400 });
  }

  if (id === session.id) {
    return Response.json(
      {
        error:
          "That is the session you are using right now. Sign out to end it, or revoke every other session instead.",
      },
      { status: 409 },
    );
  }

  const { count } = await db.session.deleteMany({ where: { id, userId: session.userId } });
  if (count === 0) {
    // Same answer for "already ended" and "belongs to somebody else". The
    // second must not be distinguishable from the first.
    return Response.json({ error: "That session has already ended." }, { status: 404 });
  }

  return Response.json({ revoked: count, signedOut: false });
}

// Dates in this section are formatted on the SERVER, in UTC, with an explicit
// locale — and then handed to the client as finished strings.
//
// Both halves of that matter. A Server Component's output is never re-run in
// the browser, but the Client Components below it are, and `toLocaleString()`
// inside one produces the host's locale on the server and the visitor's on
// hydration: two different strings for the same instant, which React reports
// as a mismatch and repaints. Pinning the locale and the zone removes the
// disagreement, and saying "UTC" out loud is the price of not silently showing
// someone a timestamp in a timezone that is not theirs.

const DATE_TIME = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hour12: false,
  timeZone: "UTC",
});

const DATE_ONLY = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

/** e.g. "20 Aug 2026, 14:32 UTC". */
export function formatDateTime(value: Date | string): string {
  return `${DATE_TIME.format(new Date(value))} UTC`;
}

/** e.g. "20 Aug 2026". No time, so no timezone caveat is needed. */
export function formatDate(value: Date | string): string {
  return DATE_ONLY.format(new Date(value));
}

/** "1 day" / "6 days" / "18 hours" — for a countdown, never for a timestamp. */
export function formatHoursLeft(hours: number): string {
  if (hours <= 1) return "under an hour";
  if (hours < 48) return `${hours} hours`;
  return `${Math.ceil(hours / 24)} days`;
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { CreditCard, ShieldCheck, UserRound } from "lucide-react";
import type { LucideIcon } from "lucide-react";

/* WHY REAL ROUTES AND NOT A CLIENT TAB COMPONENT
   ─────────────────────────────────────────────
   Each section is a Server Component with its own queries, and they are not
   cheap ones: Security counts and lists sessions and computes the deletion
   preview (eleven counts across nine tables), Credits aggregates 30 days of
   the ledger. A single page with client-side tabs would run all of that on
   every visit to Settings, to render one panel.

   Three more things fall out of using the router rather than useState:
   a section is linkable and survives a reload (the Discord OAuth callback
   redirects to /settings with an outcome in the query string, and it has to
   land somewhere specific); Back does what it looks like it does; and the
   only client JavaScript on the Account tab is the name field itself.

   This component is a Client Component solely to read the pathname for the
   active state — it holds no state of its own. */

type Tab = { href: string; label: string; icon: LucideIcon; exact?: boolean };

const TABS: Tab[] = [
  { href: "/settings", label: "Account", icon: UserRound, exact: true },
  { href: "/settings/credits", label: "Credits", icon: CreditCard },
  { href: "/settings/security", label: "Security", icon: ShieldCheck },
];

export default function SettingsNav() {
  const pathname = usePathname();

  return (
    <nav aria-label="Settings sections" className="k-scroll-x -mx-1 px-1">
      <ul className="flex min-w-max items-center gap-1 border-b border-hair pb-px">
        {TABS.map((tab) => {
          const active = tab.exact ? pathname === tab.href : pathname.startsWith(tab.href);
          const Icon = tab.icon;
          return (
            <li key={tab.href}>
              <Link
                href={tab.href}
                aria-current={active ? "page" : undefined}
                className={[
                  "k-focus relative -mb-px inline-flex items-center gap-2 rounded-t-md px-3 py-2.5 text-sm font-medium",
                  "border-b-2 transition-colors duration-[var(--t-1)]",
                  active
                    ? "border-brand text-ink"
                    : "border-transparent text-ink-2 hover:border-line-mid hover:text-ink",
                ].join(" ")}
              >
                <Icon className="size-4" aria-hidden />
                {tab.label}
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

