"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Field";
import { useToast } from "@/components/ui/Toast";
import { MAX_NAME_LENGTH } from "@/app/api/account/_profile";

/* The display name, and the only editable field on the account.
   PUTs /api/account/profile, then router.refresh() — the name is rendered by
   the sidebar, the avatar and the dashboard greeting, all of which are Server
   Components above this one, so a refresh is what makes the whole shell agree
   with the field instead of this input being the only thing that changed. */
export default function NameForm({ initialName }: { initialName: string | null }) {
  const router = useRouter();
  const toast = useToast();
  const [saved, setSaved] = useState(initialName ?? "");
  const [value, setValue] = useState(initialName ?? "");
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [refreshing, startTransition] = useTransition();

  // Compared against the last SAVED value rather than the initial prop, so the
  // button goes quiet again after a save instead of staying lit until a
  // navigation. Trimmed on both sides because trailing space is not an edit —
  // the server would normalise it away and report nothing changed.
  const dirty = value.trim() !== saved.trim();
  const busy = saving || refreshing;

  async function save() {
    setSaving(true);
    setError(null);
    try {
      const res = await fetch("/api/account/profile", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        // Empty clears the name; the route treats "" and null identically.
        body: JSON.stringify({ name: value.trim() === "" ? null : value }),
      });
      const data = (await res.json()) as { name?: string | null; error?: string };
      if (!res.ok) {
        setError(data.error ?? "Couldn't save that.");
        return;
      }
      // Show what was STORED, not what was typed: the server collapses runs of
      // whitespace and strips invisible characters, and the field should not
      // keep claiming otherwise.
      const stored = data.name ?? "";
      setSaved(stored);
      setValue(stored);
      toast({
        tone: "ok",
        message: data.name === null ? "Name removed." : `Name saved as “${data.name}”.`,
      });
      startTransition(() => router.refresh());
    } catch {
      setError("Couldn't reach the server. Try again.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form
      className="mt-4 flex flex-wrap items-end gap-3"
      onSubmit={(e) => {
        e.preventDefault();
        if (dirty && !busy) void save();
      }}
    >
      <div className="min-w-56 flex-1">
        <Input
          label="Display name"
          value={value}
          onChange={(e) => {
            setValue(e.target.value);
            setError(null);
          }}
          error={error ?? undefined}
          hint={`Up to ${MAX_NAME_LENGTH} characters. Leave it empty to go by your email address instead.`}
          maxLength={MAX_NAME_LENGTH}
          autoComplete="name"
          spellCheck={false}
          placeholder="Your name"
          disabled={busy}
        />
      </div>
      {/* The one primary action on this page. */}
      <Button type="submit" variant="primary" disabled={!dirty} loading={busy} className="mb-6">
        Save
      </Button>
    </form>
  );
}

import { redirect } from "next/navigation";
import Link from "next/link";
import { Mail } from "lucide-react";
import { getCurrentUser } from "@/lib/auth";
import { Card, CardHeader } from "@/components/ui/Card";
import { EmptyState } from "@/components/ui/EmptyState";
import { PRIVACY_EMAIL } from "@/app/api/account/_deletion";
import NameForm from "./NameForm";
import { formatDate } from "./_format";

export const dynamic = "force-dynamic";

/* ACCOUNT — who you are on Kodely.
   One editable field (the name), one read-only one (the email), and a plain
   statement about the emails we send. Nothing on this page is a control that
   does not do something. */
export default async function SettingsAccountPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  // app/api/rewards/discord/{start,callback} redirect to /settings?reward=…
  // and predate this section split. Free credits now live on the Credits tab,
  // so the outcome is forwarded there rather than silently dropped on a page
  // that no longer has a rewards card to show it in. Fixing this here keeps
  // the change out of the rewards routes entirely.
  const reward = (await searchParams).reward;
  if (typeof reward === "string" && reward.length > 0) {
    redirect(`/settings/credits?reward=${encodeURIComponent(reward)}`);
  }

  return (
    <>
      <Card>
        <CardHeader
          title="Profile"
          description="Your name is what the portal greets you with and what your welcome email is addressed to. It is never shown on a site you publish."
        />
        <NameForm initialName={user.name} />
      </Card>

      <Card>
        <CardHeader title="Email address" />
        <div className="mt-4 flex flex-wrap items-center gap-3 rounded-md border border-hair bg-surface-2 px-3.5 py-2.5">
          <Mail className="size-4 shrink-0 text-ink-3" aria-hidden />
          <span className="min-w-0 flex-1 truncate text-sm text-ink">{user.email}</span>
        </div>
        <p className="mt-3 text-[0.8125rem] leading-relaxed text-ink-2">
          This is the address you sign in with, and it cannot be changed here — there is no
          self-serve route for it, and a box that looked editable and saved nothing would be worse
          than this line. Email{" "}
          <a
            href={`mailto:${PRIVACY_EMAIL}`}
            className="k-focus rounded-xs text-brand underline underline-offset-2 hover:no-underline"
          >
            {PRIVACY_EMAIL}
          </a>{" "}
          and a person will change it for you.
        </p>
        <p className="mt-3 text-[0.8125rem] text-ink-2">
          Member since <span className="k-num text-ink">{formatDate(user.createdAt)}</span>.
        </p>
      </Card>

      {/* SURFACED, NOT OMITTED. "Where do I turn the emails off?" is a question
          people come to a settings page with, and the answer here is a real
          one: there is nothing to turn off. lib/notifications/templates.ts is
          explicit that this product holds no consent record and has no
          unsubscribe mechanism, precisely because all four messages are
          triggered by the recipient's own account. Naming the four is more
          use than four switches that write nowhere. */}
      <EmptyState
        kind="unavailable"
        icon={<Mail className="size-6" aria-hidden />}
        title="No email preferences to set"
        body={
          <>
            Kodely sends four emails, each one triggered by something on your own account: a
            welcome, a warning when your credits run low, a note when a build fails, and a
            confirmation when a site goes live. There is no marketing list, no newsletter and no
            tracking pixel — so there is nothing here to opt out of, and no switch has been drawn
            that would pretend otherwise. The full record of what was sent to you is in your{" "}
            <Link
              href="/settings/security"
              className="k-focus rounded-xs text-brand underline underline-offset-2 hover:no-underline"
            >
              data export
            </Link>
            .
          </>
        }
      />
    </>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Field";
import { useToast } from "@/components/ui/Toast";

/* The user's own ceiling on 30-day spend. The route (app/api/account/
   spend-cap) is unchanged; this is the same PUT it always sent, wearing the
   product's own controls instead of a hand-rolled checkbox and a bare input. */

type Props = { initialCap: number | null; spent: number };

export default function SpendCapForm({ initialCap, spent }: Props) {
  const toast = useToast();
  const [enabled, setEnabled] = useState(initialCap !== null);
  const [value, setValue] = useState(initialCap === null ? "" : String(initialCap));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function save() {
    setSaving(true);
    setError(null);

    const cap = enabled ? Number(value) : null;
    if (enabled && (!Number.isInteger(cap) || (cap as number) < 1)) {
      setError("Enter a whole number of credits.");
      setSaving(false);
      return;
    }

    try {
      const res = await fetch("/api/account/spend-cap", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ cap }),
      });
      const data = (await res.json()) as { cap?: number | null; error?: string };
      if (!res.ok) {
        setError(data.error ?? "Couldn't save that.");
        return;
      }
      toast({
        tone: "ok",
        message:
          data.cap == null
            ? "Cap removed. Builds will run until your credits run out."
            : `Cap set to ${data.cap.toLocaleString()} credits per 30 days.`,
      });
    } catch {
      setError("Couldn't reach the server. Try again.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="mt-5">
      <label className="flex w-fit cursor-pointer items-center gap-2.5 text-sm text-ink">
        <input
          type="checkbox"
          checked={enabled}
          onChange={(e) => {
            setEnabled(e.target.checked);
            setError(null);
          }}
          className="k-focus size-4 rounded-xs border-line-strong accent-[var(--brand)]"
        />
        Limit my spending
      </label>

      {enabled && (
        <div className="mt-4 flex max-w-xs items-start gap-2">
          <Input
            label="Credits per 30 days"
            type="number"
            min={1}
            step={1}
            inputMode="numeric"
            value={value}
            onChange={(e) => {
              setValue(e.target.value);
              setError(null);
            }}
            error={error ?? undefined}
            placeholder="1000"
            className="k-num"
          />
        </div>
      )}

      {!enabled && error != null && <p className="mt-3 text-xs text-danger">{error}</p>}

      <div className="mt-4 flex items-center gap-3">
        {/* The one primary action on this page. */}
        <Button variant="primary" size="sm" onClick={save} loading={saving}>
          Save
        </Button>
        <span className="text-xs text-ink-3">
          {enabled
            ? "Builds stop when the cap is reached. Nothing else changes."
            : "No cap. Builds run until your credit balance runs out."}
        </span>
      </div>

      <p className="sr-only">
        You have spent {spent} credits in the last 30 days.
      </p>
    </div>
  );
}

