import { redirect } from "next/navigation";
import Link from "next/link";
import { getCurrentUser } from "@/lib/auth";
import { getSpendCapStatus, spentInWindow } from "@/lib/credits";
import {
  MIN_ACCOUNT_AGE_HOURS,
  rewardStatuses,
  UNVERIFIED_HOLD_HOURS,
} from "@/app/api/rewards/_lib";
import { Card, CardHeader } from "@/components/ui/Card";
import { Badge } from "@/components/ui/Badge";
import { Progress, toneForUsage } from "@/components/ui/Progress";
import RewardsCard from "@/components/rewards/RewardsCard";
import SpendCapForm from "../SpendCapForm";

export const dynamic = "force-dynamic";

/* CREDITS — the two things about money that live in Settings.
   The credit ledger itself, top-ups and purchase history are /dashboard/billing
   and stay there; this page is only the things you SET rather than read. */
export default async function SettingsCreditsPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const [cap, rewards, params] = await Promise.all([
    getSpendCapStatus(user.id),
    // Returns [] when no reward platform is configured, so the card renders
    // nothing at all rather than this page needing to know about env vars.
    rewardStatuses(user),
    searchParams,
  ]);

  // getSpendCapStatus skips the spend query when uncapped (there is nothing to
  // compare against), but this page shows recent spend either way.
  const spent = cap.cap === null ? await spentInWindow(user.id) : cap.spent;

  // Set by the Discord OAuth callback on its way back here, via /settings.
  const notice = params.reward;

  return (
    <>
      <Card>
        <CardHeader
          title="Spending cap"
          description="Stop builds once you have spent this many credits in any 30-day period. Your cap, your call — we will never raise it for you."
          action={
            cap.reached ? (
              <Badge tone="danger" dot>
                Cap reached
              </Badge>
            ) : cap.cap !== null ? (
              <Badge tone="ok" dot>
                Cap on
              </Badge>
            ) : (
              <Badge tone="neutral">No cap</Badge>
            )
          }
        />

        <div className="mt-5 rounded-lg border border-hair bg-surface-2 p-4">
          <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
            <span className="k-label">Spent in the last 30 days</span>
            <span className="text-sm text-ink-2">
              <span className="k-num font-semibold text-ink">{spent.toLocaleString()}</span>
              {cap.cap !== null && (
                <>
                  {" of "}
                  <span className="k-num font-semibold text-ink">{cap.cap.toLocaleString()}</span>
                </>
              )}{" "}
              credits
            </span>
          </div>
          {cap.cap !== null && (
            <Progress
              className="mt-3"
              value={spent}
              max={cap.cap}
              tone={toneForUsage(spent / cap.cap)}
              label="Credits spent against your cap"
            />
          )}
          <p className="mt-3 text-xs leading-relaxed text-ink-3">
            A rolling 30 days, not a calendar month — there is no reset day, and credits themselves
            never expire. Everything you have spent, line by line, is in{" "}
            <Link
              href="/dashboard/billing"
              className="k-focus rounded-xs text-brand underline underline-offset-2 hover:no-underline"
            >
              Billing
            </Link>
            .
          </p>
        </div>

        <SpendCapForm initialCap={cap.cap} spent={spent} />
      </Card>

      {/* Renders nothing when no reward platform is configured. Not an empty
          state — no state. */}
      <RewardsCard
        rewards={rewards}
        holdHours={UNVERIFIED_HOLD_HOURS}
        unlockHours={MIN_ACCOUNT_AGE_HOURS}
        notice={typeof notice === "string" ? notice : undefined}
      />
    </>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import type { RewardStatus } from "@/app/api/rewards/_lib";
import { Button, buttonClass } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Card, CardHeader } from "@/components/ui/Card";

// The free-credits section of /settings/credits. Renders nothing at all when
// no reward is configured — an unconfigured reward is not an error state to
// explain, it is simply a thing that does not exist yet.
//
// The UI does not pretend the four rewards are equivalent. Discord says
// "verified"; the other three say the credits are held for a few days, because
// that hold is the only thing standing in for a check. See
// app/api/rewards/social/_unverified.ts.
//
// Presentation only was moved onto the product design system when Settings was
// split into sections — every fetch, every state transition and every route
// this component calls is unchanged.

type Props = {
  rewards: RewardStatus[];
  holdHours: number;
  unlockHours: number;
  /** Outcome of a Discord round trip, from ?reward= on the callback redirect. */
  notice?: string;
};

const NOTICES: Record<string, { kind: "ok" | "error"; text: string }> = {
  discord_ok: { kind: "ok", text: "Discord verified — 50 credits added." },
  not_member: {
    kind: "error",
    text: "We couldn't find you in the Discord server. Join first, then try again.",
  },
  discord_taken: {
    kind: "error",
    text: "That Discord account has already claimed this reward on another Kodely account.",
  },
  already: { kind: "error", text: "You've already claimed that one." },
  too_new: { kind: "error", text: "Rewards unlock a day after signup." },
  paused: { kind: "error", text: "Reward claims are paused for a moment. Try again shortly." },
  unavailable: { kind: "error", text: "That reward isn't available right now." },
  failed: { kind: "error", text: "Couldn't confirm that with Discord. Try again." },
};

export default function RewardsCard({ rewards, holdHours, unlockHours, notice }: Props) {
  const router = useRouter();
  const [pending, startTransition] = useTransition();
  const [handles, setHandles] = useState<Record<string, string>>({});
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);

  // No configured rewards, nothing to show. Not an empty state — no state.
  if (rewards.length === 0) return null;

  const banner = notice ? NOTICES[notice] : undefined;
  const earned = rewards
    .filter((r) => r.state === "claimed")
    .reduce((sum, r) => sum + r.credits, 0);
  const total = rewards.reduce((sum, r) => sum + r.credits, 0);

  async function post(url: string, body: unknown) {
    setError(null);
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(body),
      });
      const data = (await res.json()) as { error?: string };
      if (!res.ok) {
        setError(data.error ?? "Something went wrong.");
        return false;
      }
      startTransition(() => router.refresh());
      return true;
    } catch {
      setError("Couldn't reach the server. Try again.");
      return false;
    }
  }

  async function connect(platform: string) {
    const handle = (handles[platform] ?? "").trim();
    if (handle.length === 0) {
      setError("Enter your username first.");
      return;
    }
    setBusy(platform);
    await post("/api/rewards/social/connect", { platform, handle });
    setBusy(null);
  }

  async function claim(platform: string) {
    setBusy(platform);
    await post("/api/rewards/social/claim", { platform });
    setBusy(null);
  }

  return (
    <Card>
      <CardHeader
        title="Free credits"
        description={`Follow along and we'll top you up — ${rewards[0].credits} credits per platform, once per account.`}
        action={
          <span className="text-sm text-ink-2">
            <span className="k-num font-semibold text-ink">{earned}</span>
            <span className="k-num"> / {total}</span> claimed
          </span>
        }
      />

      {banner && (
        <p
          className={`mt-4 rounded-md px-3 py-2 text-[0.8125rem] ${
            banner.kind === "ok" ? "bg-ok-tint text-ok" : "bg-danger-tint text-danger"
          }`}
        >
          {banner.text}
        </p>
      )}

      <ul className="mt-4 divide-y divide-hair">
        {rewards.map((reward) => (
          <li key={reward.platform} className="py-3 first:pt-0 last:pb-0">
            <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-2">
              <div className="flex min-w-0 items-center gap-2">
                <span className="text-sm font-medium text-ink">{reward.label}</span>
                <span className="k-num text-sm text-ink-3">+{reward.credits}</span>
                {reward.verified && (
                  <Badge tone="info">verified automatically</Badge>
                )}
              </div>

              <Action
                reward={reward}
                holdHours={holdHours}
                unlockHours={unlockHours}
                busy={busy === reward.platform || pending}
                handle={handles[reward.platform] ?? ""}
                onHandle={(value) =>
                  setHandles((prev) => ({ ...prev, [reward.platform]: value }))
                }
                onConnect={() => connect(reward.platform)}
                onClaim={() => claim(reward.platform)}
              />
            </div>
          </li>
        ))}
      </ul>

      {error && <p className="mt-3 text-[0.8125rem] text-danger">{error}</p>}

      {/* Say the quiet part out loud rather than letting the delay look like a
          bug. The user is being told, accurately, why one reward is instant
          and the others are not. */}
      {rewards.some((r) => !r.verified) && (
        <p className="mt-4 text-xs leading-relaxed text-ink-3">
          Only Discord can be checked automatically. The others go on your word, so those credits
          are held for {formatHours(holdHours)} first.
        </p>
      )}
    </Card>
  );
}

function Action({
  reward,
  holdHours,
  unlockHours,
  busy,
  handle,
  onHandle,
  onConnect,
  onClaim,
}: {
  reward: RewardStatus;
  holdHours: number;
  unlockHours: number;
  busy: boolean;
  handle: string;
  onHandle: (value: string) => void;
  onConnect: () => void;
  onClaim: () => void;
}) {
  const muted = "text-[0.8125rem] text-ink-3";
  const link =
    "k-focus rounded-xs text-[0.8125rem] text-ink-2 underline underline-offset-2 hover:text-ink hover:no-underline";

  if (reward.state === "claimed") {
    return (
      <Badge tone="ok" dot>
        Claimed
      </Badge>
    );
  }

  if (reward.state === "locked") {
    return <span className={muted}>Unlocks {unlockHours}h after signup</span>;
  }

  if (reward.state === "pending") {
    return (
      <span className={muted}>
        Connected — credits in {formatHours(reward.readyInHours ?? holdHours)}
      </span>
    );
  }

  if (reward.state === "claimable") {
    return (
      <Button variant="soft" size="sm" onClick={onClaim} loading={busy}>
        Claim {reward.credits}
      </Button>
    );
  }

  // state === "available"
  if (reward.verified) {
    return (
      <div className="flex items-center gap-3">
        <a href={reward.url} target="_blank" rel="noreferrer noopener" className={link}>
          Join
        </a>
        {/* A plain link, not fetch: this starts an OAuth redirect chain. */}
        <a href="/api/rewards/discord/start" className={buttonClass({ variant: "soft", size: "sm" })}>
          Verify
        </a>
      </div>
    );
  }

  return (
    <div className="flex flex-wrap items-center gap-2">
      <a href={reward.url} target="_blank" rel="noreferrer noopener" className={link}>
        Open
      </a>
      <input
        value={handle}
        onChange={(e) => onHandle(e.target.value)}
        placeholder="your username"
        aria-label={`Your ${reward.label} username`}
        className="k-focus h-8 w-40 rounded-md border border-line-mid bg-surface px-3 text-[0.8125rem] text-ink placeholder:text-ink-3 focus:border-brand focus:outline-none"
      />
      <Button variant="soft" size="sm" onClick={onConnect} loading={busy}>
        I followed
      </Button>
    </div>
  );
}

function formatHours(hours: number): string {
  if (hours <= 1) return "under an hour";
  if (hours < 24) return `${hours} hours`;
  const days = Math.ceil(hours / 24);
  return days === 1 ? "a day" : `${days} days`;
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { ConfirmModal } from "@/components/ui/Modal";
import { useToast } from "@/components/ui/Toast";

/* Active sessions, and the three ways to end them.

   Everything shown here is a fact the Session row actually holds: when the
   sign-in happened, when the session stops working, and which one is this
   browser. There is no device column, no browser column and no location,
   because the table records none of those — see app/api/account/_sessions.ts
   for what was considered and why nothing was invented.

   Dates arrive pre-formatted from the server. Formatting them here would
   produce one string during the server render and a different one on
   hydration, which is a mismatch React repaints over. */

export type DisplaySession = {
  id: string;
  current: boolean;
  createdAtIso: string;
  createdAtLabel: string;
  expiresAtIso: string;
  expiresAtLabel: string;
};

type Scope = "others" | "all";

export default function SessionList({
  sessions,
  total,
  limit,
}: {
  sessions: DisplaySession[];
  total: number;
  limit: number;
}) {
  const router = useRouter();
  const toast = useToast();
  const [revoking, setRevoking] = useState<string | null>(null);
  const [confirming, setConfirming] = useState<Scope | null>(null);
  const [bulkBusy, setBulkBusy] = useState(false);
  const [refreshing, startTransition] = useTransition();

  const others = total - sessions.filter((s) => s.current).length;

  async function revoke(body: { id: string } | { scope: Scope }) {
    const res = await fetch("/api/account/sessions", {
      method: "DELETE",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    return { res, data: (await res.json()) as { revoked?: number; signedOut?: boolean; error?: string } };
  }

  async function revokeOne(id: string) {
    setRevoking(id);
    try {
      const { res, data } = await revoke({ id });
      if (!res.ok) {
        toast({ tone: "danger", message: data.error ?? "Couldn't end that session." });
        return;
      }
      toast({ tone: "ok", message: "That session was signed out." });
      startTransition(() => router.refresh());
    } catch {
      toast({ tone: "danger", message: "Couldn't reach the server. Try again." });
    } finally {
      setRevoking(null);
    }
  }

  async function revokeScope(scope: Scope) {
    setBulkBusy(true);
    try {
      const { res, data } = await revoke({ scope });
      if (!res.ok) {
        toast({ tone: "danger", message: data.error ?? "Couldn't end those sessions." });
        return;
      }
      setConfirming(null);
      if (data.signedOut) {
        // Every row is gone and the cookie has been cleared, so this page is
        // already unauthenticated. A hard navigation rather than router.push:
        // nothing in the client cache above this component is valid any more.
        window.location.assign("/login");
        return;
      }
      const count = data.revoked ?? 0;
      toast({
        tone: "ok",
        message:
          count === 0
            ? "There were no other sessions to sign out."
            : `Signed out ${count} other session${count === 1 ? "" : "s"}.`,
      });
      startTransition(() => router.refresh());
    } catch {
      toast({ tone: "danger", message: "Couldn't reach the server. Try again." });
    } finally {
      setBulkBusy(false);
    }
  }

  return (
    <>
      <ul className="mt-5 divide-y divide-hair rounded-lg border border-hair">
        {sessions.map((session) => (
          <li
            key={session.id}
            className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2 px-4 py-3"
          >
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <span className="text-sm font-medium text-ink">
                  Signed in{" "}
                  <time className="k-num" dateTime={session.createdAtIso}>
                    {session.createdAtLabel}
                  </time>
                </span>
                {session.current && (
                  <Badge tone="ok" dot>
                    This device
                  </Badge>
                )}
              </div>
              <p className="mt-0.5 text-xs text-ink-3">
                Expires{" "}
                <time className="k-num" dateTime={session.expiresAtIso}>
                  {session.expiresAtLabel}
                </time>
              </p>
            </div>

            {session.current ? (
              <span className="text-xs text-ink-3">Sign out to end this one</span>
            ) : (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => void revokeOne(session.id)}
                loading={revoking === session.id}
                disabled={bulkBusy || refreshing}
              >
                Sign out
              </Button>
            )}
          </li>
        ))}
      </ul>

      {total > sessions.length && (
        <p className="mt-3 text-xs text-ink-3">
          Showing the {limit} most recent of{" "}
          <span className="k-num">{total.toLocaleString()}</span> active sessions. Signing out every
          other session below ends all of them, not just the ones listed.
        </p>
      )}

      {others > 0 && (
        <div className="mt-4 flex flex-wrap items-center gap-3">
          <Button
            variant="secondary"
            size="sm"
            onClick={() => setConfirming("others")}
            disabled={bulkBusy || refreshing}
          >
            Sign out {others === 1 ? "the other session" : `all ${others} other sessions`}
          </Button>
          <button
            type="button"
            className="k-focus rounded-xs text-xs text-danger underline underline-offset-2 hover:no-underline disabled:opacity-45"
            onClick={() => setConfirming("all")}
            disabled={bulkBusy || refreshing}
          >
            Sign out everywhere, including this device
          </button>
        </div>
      )}

      <ConfirmModal
        open={confirming === "others"}
        onClose={() => setConfirming(null)}
        onConfirm={() => void revokeScope("others")}
        title="Sign out every other session?"
        confirmLabel="Sign out others"
        busy={bulkBusy}
        body={
          <>
            Every other browser and device signed in to this account is signed out immediately, and
            has to sign in again. You stay signed in here. Nothing else about your account changes —
            no project, file or credit is touched.
          </>
        }
      />

      <ConfirmModal
        open={confirming === "all"}
        onClose={() => setConfirming(null)}
        onConfirm={() => void revokeScope("all")}
        title="Sign out everywhere?"
        confirmLabel="Sign out everywhere"
        busy={bulkBusy}
        body={
          <>
            This one includes the browser you are using right now — you will be sent to the sign-in
            page and will need your password or Google account to get back in. Use it if you think
            somebody else has access. Nothing is deleted.
          </>
        }
      />
    </>
  );
}

