"use client";

import { useEffect, useRef, useState } from "react";
import { Download } from "lucide-react";
import { buttonClass } from "@/components/ui/Button";

/* A plain <a>, not a fetch and not next/link: the route answers with a
   Content-Disposition attachment and a streamed body, so the browser's own
   download machinery is exactly the right thing. A client-side fetch would
   buffer the whole account in memory to hand it straight back to the browser.

   The cooldown mirrors the route's own one-per-minute throttle
   (app/api/account/export/route.ts) so an impatient second click is greyed out
   here rather than answered with a 429 the user cannot see — a failed download
   with no visible error is the worst version of this. */

const COOLDOWN_MS = 60_000;

export default function DataExportButton() {
  const [cooling, setCooling] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => () => {
    if (timer.current) clearTimeout(timer.current);
  }, []);

  if (cooling) {
    return (
      <span
        aria-live="polite"
        className={buttonClass({ variant: "secondary", size: "sm", className: "pointer-events-none opacity-50" })}
      >
        <Download className="size-4" aria-hidden />
        Preparing your download…
      </span>
    );
  }

  return (
    <a
      href="/api/account/export"
      className={buttonClass({ variant: "secondary", size: "sm" })}
      onClick={() => {
        setCooling(true);
        timer.current = setTimeout(() => setCooling(false), COOLDOWN_MS);
      }}
    >
      <Download className="size-4" aria-hidden />
      Download my data (JSON)
    </a>
  );
}

"use client";

import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/Button";
import { Input } from "@/components/ui/Field";
import { Badge } from "@/components/ui/Badge";
import { useToast } from "@/components/ui/Toast";

/* THE DANGER ZONE — the same two-step erasure that /legal/rights offers,
   surfaced where someone closing their account will actually look for it.

   NO LOGIC IS DUPLICATED. Every decision — whether a request exists, whether
   the grace period has elapsed, what would be destroyed, what survives and why
   — lives in app/api/account/_deletion.ts and the two routes over it. The
   status and the preview here are rendered by the SERVER from those same
   functions, and these three buttons call those same routes. This file
   contributes markup and confirmation wording, nothing else.

   The marketing panel at /legal/rights keeps its own copy on purpose: that
   page has to work for someone who cannot reach the portal, and it is the
   address the deletion email points at. */

export type DeletionView =
  | { state: "none" }
  | { state: "pending"; requestedAt: string; scheduledFor: string; timeLeft: string }
  | { state: "due"; requestedAt: string; scheduledFor: string }
  | { state: "erased"; erasedAt: string };

export type DeletionCounts = {
  projects: number;
  liveSites: number;
  files: number;
  messages: number;
  builds: number;
  sessions: number;
  supportNotes: number;
  emailsSent: number;
  analyticsEvents: number;
  creditLedgerRows: number;
  creditBalance: number;
};

type Receipt = {
  projectsDeleted: number;
  liveSitesWithdrawn: number;
  filesDeleted: number;
  messagesDeleted: number;
  buildsDeleted: number;
  sessionsEnded: number;
  analyticsEventsDetached: number;
  supportNotesDeleted: number;
  emailRecordsDeleted: number;
  creditLedgerRowsRetained: number;
  moderationFindingsRetained: number;
};

function Rows({ items }: { items: [string, number | string][] }) {
  return (
    <dl className="mt-2 text-[0.8125rem]">
      {items.map(([label, value]) => (
        <div
          key={label}
          className="flex items-baseline justify-between gap-4 border-b border-hair py-1.5 last:border-0"
        >
          <dt className="text-ink-2">{label}</dt>
          <dd className="k-num font-medium text-ink">
            {typeof value === "number" ? value.toLocaleString() : value}
          </dd>
        </div>
      ))}
    </dl>
  );
}

export default function DeleteAccountPanel({
  view,
  counts,
  graceDays,
  confirmationPhrase,
  contactEmail,
}: {
  view: DeletionView;
  counts: DeletionCounts;
  graceDays: number;
  confirmationPhrase: string;
  contactEmail: string;
}) {
  const router = useRouter();
  const toast = useToast();
  const [phrase, setPhrase] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [receipt, setReceipt] = useState<Receipt | null>(null);
  const [refreshing, startTransition] = useTransition();

  const phraseOk = phrase === confirmationPhrase;
  const working = busy || refreshing;

  async function send(method: "POST" | "DELETE", url: string) {
    setBusy(true);
    setError(null);
    try {
      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: method === "POST" ? JSON.stringify({ confirm: phrase }) : undefined,
      });
      const data = (await res.json()) as { error?: string; receipt?: Receipt };
      if (!res.ok) {
        setError(data.error ?? "That did not work. Try again.");
        return;
      }
      if (data.receipt) {
        // The account is gone and the session with it. Nothing on this page can
        // be refreshed any more, so the receipt replaces the panel in place —
        // it is the only chance to read what happened.
        setReceipt(data.receipt);
        return;
      }
      setPhrase("");
      toast({
        tone: "ok",
        message:
          method === "DELETE"
            ? "Deletion request cancelled. Nothing was deleted."
            : `Deletion requested. Nothing is deleted for ${graceDays} days, and we have emailed you.`,
      });
      startTransition(() => router.refresh());
    } catch {
      setError("Couldn't reach the server. Try again.");
    } finally {
      setBusy(false);
    }
  }

  if (receipt) {
    return (
      <div>
        <h3 className="k-h2 text-ink">Your account has been deleted</h3>
        <p className="mt-1 text-[0.8125rem] leading-relaxed text-ink-2">
          You are signed out. Here is exactly what happened.
        </p>

        <p className="k-label mt-5">Destroyed</p>
        <Rows
          items={[
            ["Projects", receipt.projectsDeleted],
            ["Published sites taken offline", receipt.liveSitesWithdrawn],
            ["Files", receipt.filesDeleted],
            ["Chat messages", receipt.messagesDeleted],
            ["Build records and snapshots", receipt.buildsDeleted],
            ["Sign-in sessions", receipt.sessionsEnded],
            ["Operator notes", receipt.supportNotesDeleted],
            ["Email delivery records", receipt.emailRecordsDeleted],
            ["Email, name, password, linked accounts", "all"],
          ]}
        />

        <p className="k-label mt-5">Kept</p>
        <Rows
          items={[
            ["Credit ledger entries", receipt.creditLedgerRowsRetained],
            ["Analytics events (detached, not deleted)", receipt.analyticsEventsDetached],
            ["Publish moderation findings", receipt.moderationFindingsRetained],
          ]}
        />
        <p className="mt-3 text-[0.8125rem] leading-relaxed text-ink-2">
          None of the kept rows carries your email address, your name or your sign-in details. Why
          each one survives is set out in full on{" "}
          <Link
            href="/legal/rights"
            className="k-focus rounded-xs text-brand underline underline-offset-2 hover:no-underline"
          >
            Your data and your rights
          </Link>
          .
        </p>
      </div>
    );
  }

  return (
    <div>
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div className="min-w-0">
          <h3 className="k-h2 text-ink">Delete your account</h3>
          <p className="mt-1 text-[0.8125rem] leading-relaxed text-ink-2">
            Irreversible. There is no soft-delete, no undo and no backup anyone here can restore
            from.
          </p>
        </div>
        {view.state === "pending" && (
          <Badge tone="warn" dot pulse>
            Deletion requested
          </Badge>
        )}
        {view.state === "due" && (
          <Badge tone="danger" dot pulse>
            Awaiting final confirmation
          </Badge>
        )}
      </div>

      {view.state === "none" && (
        <>
          <p className="mt-4 text-[0.8125rem] leading-relaxed text-ink-2">
            This is a request, not a button that fires immediately. Nothing is destroyed for{" "}
            <span className="font-medium text-ink">{graceDays} days</span>, your account keeps
            working in the meantime, we email you the moment a request is made, and you can cancel
            at any point before you confirm it.
          </p>

          <p className="k-label mt-5">What would be destroyed</p>
          <Rows
            items={[
              ["Projects", counts.projects],
              ["Published sites (taken offline)", counts.liveSites],
              ["Files", counts.files],
              ["Chat messages", counts.messages],
              ["Build records and snapshots", counts.builds],
              ["Sign-in sessions", counts.sessions],
              ["Operator notes", counts.supportNotes],
              ["Email delivery records", counts.emailsSent],
              ["Email, name, password, linked accounts", "all"],
            ]}
          />

          <p className="k-label mt-5">What would be kept</p>
          <Rows
            items={[
              ["Credit ledger entries", counts.creditLedgerRows],
              ["Analytics events (detached, not deleted)", counts.analyticsEvents],
            ]}
          />
          {counts.creditBalance > 0 && (
            <p className="mt-3 text-[0.8125rem] text-ink-2">
              Your balance of{" "}
              <span className="k-num font-medium text-ink">
                {counts.creditBalance.toLocaleString()}
              </span>{" "}
              credits goes with the account. Deleting is not a refund.
            </p>
          )}

          <div className="mt-5 max-w-sm">
            <Input
              label={`Type ${confirmationPhrase} to request deletion`}
              value={phrase}
              onChange={(e) => {
                setPhrase(e.target.value);
                setError(null);
              }}
              error={error ?? undefined}
              autoComplete="off"
              spellCheck={false}
              className="font-mono"
            />
          </div>

          <Button
            variant="danger"
            size="sm"
            className="mt-4"
            disabled={!phraseOk}
            loading={working}
            onClick={() => void send("POST", "/api/account/deletion")}
          >
            Request deletion
          </Button>
        </>
      )}

      {view.state === "pending" && (
        <>
          <p className="mt-4 text-[0.8125rem] leading-relaxed text-ink-2">
            Requested <span className="k-num text-ink">{view.requestedAt}</span>.{" "}
            <span className="font-medium text-ink">Nothing has been deleted.</span> This request can
            be carried out from <span className="k-num text-ink">{view.scheduledFor}</span> — about{" "}
            {view.timeLeft} away. Until you come back and confirm it after that date, your account
            works exactly as before.
          </p>
          <p className="mt-3 text-[0.8125rem] leading-relaxed text-ink-2">
            Did not request this? Someone else may have access to your account. Cancel below, then
            sign out every other session above.
          </p>
          {error != null && <p className="mt-3 text-xs text-danger">{error}</p>}
          <Button
            variant="secondary"
            size="sm"
            className="mt-4"
            loading={working}
            onClick={() => void send("DELETE", "/api/account/deletion")}
          >
            Cancel this request
          </Button>
        </>
      )}

      {view.state === "due" && (
        <>
          <p className="mt-4 text-[0.8125rem] leading-relaxed text-ink-2">
            Requested <span className="k-num text-ink">{view.requestedAt}</span>. The {graceDays}
            -day wait ended <span className="k-num text-ink">{view.scheduledFor}</span>.{" "}
            <span className="font-medium text-ink">Nothing has been deleted yet</span> — confirming
            below is the irreversible step, and it destroys{" "}
            <span className="k-num">{counts.projects}</span> project
            {counts.projects === 1 ? "" : "s"}
            {counts.liveSites > 0 && (
              <>
                , taking <span className="k-num">{counts.liveSites}</span> published site
                {counts.liveSites === 1 ? "" : "s"} offline
              </>
            )}
            .
          </p>

          <div className="mt-5 max-w-sm">
            <Input
              label={`Type ${confirmationPhrase} once more to delete permanently`}
              value={phrase}
              onChange={(e) => {
                setPhrase(e.target.value);
                setError(null);
              }}
              error={error ?? undefined}
              autoComplete="off"
              spellCheck={false}
              className="font-mono"
            />
          </div>

          <div className="mt-4 flex flex-wrap items-center gap-3">
            <Button
              variant="danger"
              size="sm"
              disabled={!phraseOk}
              loading={working}
              onClick={() => void send("POST", "/api/account/deletion/confirm")}
            >
              Delete my account permanently
            </Button>
            <Button
              variant="ghost"
              size="sm"
              disabled={working}
              onClick={() => void send("DELETE", "/api/account/deletion")}
            >
              Cancel this request
            </Button>
          </div>
        </>
      )}

      {view.state === "erased" && (
        <p className="mt-4 text-[0.8125rem] text-ink-2">
          This account was erased on <span className="k-num text-ink">{view.erasedAt}</span>.
        </p>
      )}

      <p className="mt-5 text-xs leading-relaxed text-ink-3">
        The full account of what deletion destroys, what survives it and why is on{" "}
        <Link
          href="/legal/rights"
          className="k-focus rounded-xs underline underline-offset-2 hover:no-underline"
        >
          Your data and your rights
        </Link>
        . If you would rather not come back to finish the second step, email{" "}
        <a
          href={`mailto:${contactEmail}`}
          className="k-focus rounded-xs underline underline-offset-2 hover:no-underline"
        >
          {contactEmail}
        </a>{" "}
        once the wait is up and a person will complete it.
      </p>
    </div>
  );
}

import { redirect } from "next/navigation";
import { KeyRound } from "lucide-react";
import { getCurrentSession, getCurrentUser } from "@/lib/auth";
import { Card, CardHeader } from "@/components/ui/Card";
import { Badge } from "@/components/ui/Badge";
import { listSessions } from "@/app/api/account/_sessions";
import {
  CONFIRMATION_PHRASE,
  DELETION_GRACE_DAYS,
  PRIVACY_EMAIL,
  deletionPreview,
  deletionStatus,
} from "@/app/api/account/_deletion";
import SessionList from "../SessionList";
import type { DisplaySession } from "../SessionList";
import DataExportButton from "../DataExportButton";
import DeleteAccountPanel from "../DeleteAccountPanel";
import type { DeletionView } from "../DeleteAccountPanel";
import { formatDateTime, formatHoursLeft } from "../_format";

export const dynamic = "force-dynamic";

/* SECURITY — everything that decides who can reach this account, and the two
   irreversible things only the account holder may do to it.

   Four real cards. Nothing on this page is a placeholder: the sign-in card
   reports what the User row actually holds, the session list is the Session
   table, and the export and deletion controls call the routes /legal/rights
   already calls. Where something does not exist — a password change, a second
   factor, a sign-in history — it is stated in the card it would have belonged
   to rather than drawn as a switch that writes nowhere. */
export default async function SettingsSecurityPage() {
  // The SESSION, not just the user: the list has to mark exactly one row as
  // this device, and only the session id can identify it.
  const [user, session] = await Promise.all([getCurrentUser(), getCurrentSession()]);
  if (!user || !session) redirect("/login");

  const [list, status, preview] = await Promise.all([
    listSessions(session.userId, session.id),
    deletionStatus(user.id),
    deletionPreview(user.id),
  ]);

  const sessions: DisplaySession[] = list.sessions.map((row) => ({
    id: row.id,
    current: row.current,
    createdAtIso: row.createdAt,
    createdAtLabel: formatDateTime(row.createdAt),
    expiresAtIso: row.expiresAt,
    expiresAtLabel: formatDateTime(row.expiresAt),
  }));

  // Booleans, never the values. passwordHash must not cross to the client even
  // as a length, and googleId is an identifier at another company.
  const hasPassword = user.passwordHash !== null;
  const hasGoogle = user.googleId !== null;

  const view: DeletionView =
    status.state === "pending"
      ? {
          state: "pending",
          requestedAt: formatDateTime(status.requestedAt),
          scheduledFor: formatDateTime(status.scheduledFor),
          timeLeft: formatHoursLeft(status.hoursLeft),
        }
      : status.state === "due"
        ? {
            state: "due",
            requestedAt: formatDateTime(status.requestedAt),
            scheduledFor: formatDateTime(status.scheduledFor),
          }
        : status.state === "erased"
          ? { state: "erased", erasedAt: formatDateTime(status.erasedAt) }
          : { state: "none" };

  return (
    <>
      <Card>
        <CardHeader
          title="How you sign in"
          action={<KeyRound className="size-4 text-ink-3" aria-hidden />}
        />
        <ul className="mt-4 flex flex-col gap-2.5">
          <li className="flex flex-wrap items-center gap-2 text-sm text-ink">
            Password
            {hasPassword ? (
              <Badge tone="ok" dot>
                Set
              </Badge>
            ) : (
              <Badge tone="neutral">Not set</Badge>
            )}
          </li>
          <li className="flex flex-wrap items-center gap-2 text-sm text-ink">
            Google
            {hasGoogle ? (
              <Badge tone="ok" dot>
                Linked
              </Badge>
            ) : (
              <Badge tone="neutral">Not linked</Badge>
            )}
          </li>
        </ul>

        {/* STATED, NOT DRAWN. Nothing in app/api writes passwordHash after the
            signup route, so there is no change-password and no reset to wire a
            button to, and there is no second-factor anywhere in the schema.
            A greyed-out "Change password" would imply a route exists. */}
        <div className="mt-5 rounded-lg border border-hair bg-surface-2 p-4 text-[0.8125rem] leading-relaxed text-ink-2">
          <p>
            <span className="font-medium text-ink">
              There is no way to change your password here, and no password reset.
            </span>{" "}
            {hasPassword
              ? "Your password was set when you signed up and nothing in the product has written it since."
              : "You sign in with Google, so this account has never had a password and cannot be given one today."}{" "}
            If you need it changed, email{" "}
            <a
              href={`mailto:${PRIVACY_EMAIL}`}
              className="k-focus rounded-xs text-brand underline underline-offset-2 hover:no-underline"
            >
              {PRIVACY_EMAIL}
            </a>
            . Until then, the strongest thing you can do if you think somebody else is signed in is
            to end their session below.
          </p>
          <p className="mt-2.5">
            Two-factor authentication does not exist yet either — no authenticator app, no SMS
            code, no recovery codes. We would rather say so than show a switch that saves nothing.
          </p>
        </div>
      </Card>

      <Card>
        <CardHeader
          title="Active sessions"
          description="Every browser currently signed in to this account. Signing one out takes effect immediately."
        />

        <SessionList
          sessions={sessions}
          total={list.total}
          // The caller's own session is live by definition — it just answered
          // this request — so everything else is exactly one fewer.
          others={Math.max(0, list.total - 1)}
          limit={list.limit}
        />

        {/* What the row genuinely knows, said plainly, so nobody reads the two
            dates as a shortened version of something richer. */}
        <p className="mt-5 text-xs leading-relaxed text-ink-3">
          A session records four things and no more: when it was created, when it expires, which
          account it belongs to, and a one-way hash of the sign-in cookie. Kodely does not store the
          browser, the device or the IP address behind a session, so this list cannot tell you
          &ldquo;Chrome on a Mac in Berlin&rdquo; — and will not guess. Sessions last 30 days and
          nothing extends them. Expired ones already do nothing and are not listed.
        </p>
        <p className="mt-2 text-xs leading-relaxed text-ink-3">
          There is no sign-in history to go with this, deliberately: failed and successful sign-in
          attempts are counted only as salted hashes in a rate-limiting bucket, with no account
          attached to them, so they can never be shown to you as &ldquo;your sign-ins&rdquo;.
        </p>
      </Card>

      <Card>
        <CardHeader
          title="Your data"
          description="One JSON file with everything the product database holds about you: your account, every project with its files, chat messages and build records, your credit ledger, your analytics events, and any operator notes written about you. The file also names what it deliberately leaves out, and why."
        />
        <div className="mt-4">
          <DataExportButton />
        </div>
        <p className="mt-3 text-xs text-ink-3">
          Generated as it downloads, so a large account takes a moment to start. One export a
          minute.
        </p>
      </Card>

      {/* The danger zone gets a red hairline rather than a red fill: it has to
          read as the end of the page, not as an error that has already
          happened. */}
      <Card className="border-danger/40">
        <DeleteAccountPanel
          view={view}
          counts={{
            projects: preview.projects,
            liveSites: preview.liveSites,
            files: preview.files,
            messages: preview.messages,
            builds: preview.builds,
            sessions: preview.sessions,
            supportNotes: preview.supportNotes,
            emailsSent: preview.emailsSent,
            analyticsEvents: preview.analyticsEvents,
            creditLedgerRows: preview.creditLedgerRows,
            creditBalance: preview.creditBalance,
          }}
          graceDays={DELETION_GRACE_DAYS}
          confirmationPhrase={CONFIRMATION_PHRASE}
          contactEmail={PRIVACY_EMAIL}
        />
      </Card>
    </>
  );
}

